// APIServer/Services/SetupFileDeletion.swift
//
// The one way a file leaves a test setup. The web `DELETE /scripts/:filename`
// routes (published and draft) and MCP `delete_support_file` all call
// `deleteFileFromSetup`, so they refuse the same files (#2771). Before, MCP ran
// the steps again by hand and skipped the `manifestDependents` check, so it
// could remove a file that a suite entry still named in its `dependsOn`.

import Core
import Fluent
import Foundation

/// Guards that the file exists, is not generated by a pattern family, is not
/// attached from the course library and is not a prerequisite of a suite
/// entry. Then it removes the file from the setup zip, drops its suite entry
/// if it has one, and clears its marks (`clearFileMarks`).
///
/// Returns true when a grader-only or dataset mark was cleared. Throws
/// `SetupFileDeletionError` for a refusal.
@discardableResult
func deleteFileFromSetup(setup: APITestSetup, filename: String, on db: any Database) async throws -> Bool {
    guard await listZipEntries(zipPath: setup.zipPath).contains(filename) else {
        throw SetupFileDeletionError.notInSetup(filename)
    }

    if let familyID = generatedByFamilyID(manifestJSON: setup.manifest, filename: filename) {
        throw SetupFileDeletionError.generatedByFamily(file: filename, familyID: familyID)
    }

    if let refusal = libraryAttachmentRefusal(manifest: setup.decodedManifest(), filename: filename) {
        throw SetupFileDeletionError.libraryAttached(refusal)
    }

    let dependents = manifestDependents(manifestJSON: setup.manifest, filename: filename)
    guard dependents.isEmpty else {
        throw SetupFileDeletionError.hasDependents(file: filename, dependents: dependents)
    }

    do {
        try await removeScriptFromZip(zipPath: setup.zipPath, filename: filename)
    } catch ScriptZipError.zipFailed, ScriptZipError.extractFailed {
        throw SetupFileDeletionError.zipUpdateFailed
    }

    // A support file has no suite entry, so the suite is not rebuilt for it.
    // Conditional, and applied again to a newer manifest if another edit
    // saved first, so that edit is kept (#2485).
    if setup.decodedManifest()?.testSuites.contains(where: { $0.script == filename }) == true {
        try await mutateManifestJSON(setup: setup, on: db) {
            updateManifestRemovingScript(manifestJSON: $0, filename: filename)
        }
    }
    var clearedMarks = false
    try await mutateManifest(setup: setup, on: db) { clearedMarks = clearFileMarks(filename, in: &$0) }
    return clearedMarks
}
